/** 
 * Sets the initial size of each input buffer. <p> This method should only be called before the decoder is used (i.e. before the first call to {@link #dequeueInputBuffer()}.
 * @param size The required input buffer size.
 */
protected final void setInitialInputBufferSize(int size){
  Assertions.checkState(availableInputBufferCount == availableInputBuffers.length);
  for (I inputBuffer : availableInputBuffers) {
    try {
      inputBuffer.ensureSpaceForWrite(size);
    } catch (IllegalStateException e) {
      // Log or handle the exception for the specific buffer
      System.err.println("Failed to ensure space for buffer: " + e.getMessage());
    }
  }
}
